CREATE TABLE _migration_0102_guard (valid INTEGER NOT NULL CHECK (valid = 1));
INSERT INTO _migration_0102_guard (valid)
SELECT CASE WHEN (SELECT COUNT(*) FROM incoming_inventory_serials) = 78
  AND (SELECT COUNT(DISTINCT material_code) FROM incoming_inventory_serials) = 57
  AND (SELECT COUNT(*) FROM incoming_inventory_serials WHERE delivery_started_on GLOB '????-??-??') = 78
  THEN 1 ELSE 0 END;
DROP TABLE _migration_0102_guard;
